    <script>function salesTargetForm(){return{items:[{productId:'',qty:1,price:0}],blank(){return{productId:'',qty:1,price:0}},remove(i){this.items.splice(i,1)},setPrice(item,event){item.price=Number(event.target.options[event.target.selectedIndex].dataset.price||0)},get totalQty(){return this.items.reduce((a,x)=>a+(Number(x.qty)||0),0)},get totalValue(){return this.items.reduce((a,x)=>a+(Number(x.qty)||0)*(Number(x.price)||0),0)},money(v){return Number(v||0).toLocaleString('en-BD',{minimumFractionDigits:2})}}}</script>
